// Original equal-scoop drawings. Patterns identify ingredients independently of color.
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let serial=0;
const color=i=>`rgb(${i.rgb.join(',')})`;
function pattern(i,id){const ink=i.id==='white'?'#5b6269':'#fffdf5';return `<pattern id="${id}" width="10" height="10" patternUnits="userSpaceOnUse"><rect width="10" height="10" fill="${color(i)}"/>${i.pattern==='dots'?`<circle cx="3" cy="3" r="1.7" fill="${ink}"/>`:i.pattern==='stripes'?`<path d="M-2 2 2-2M0 10 10 0M8 12 12 8" stroke="${ink}" stroke-width="1.6"/>`:i.pattern==='crosshatch'?`<path d="M0 0 10 10M10 0 0 10" stroke="${ink}" stroke-width="1.2"/>`:`<path d="m0 3 5 4 5-4" stroke="${ink}" stroke-width="1.6" fill="none"/>`}</pattern>`;}
function setup(pair){const id=`mt-art-${++serial}`;return {id,defs:`<defs>${pair.ingredients.map((i,n)=>pattern(i,`${id}-${n}`)).join('')}</defs>`};}
export function mixingScoops(pair,a,b,{pot=false}={}){const {id,defs}=setup(pair),total=a+b,cols=pot?8:10,rows=Math.max(1,Math.ceil(total/cols)),height=rows*22+18;const tokens=Array.from({length:total},(_,n)=>`<circle cx="${15+(n%cols)*23}" cy="${15+Math.floor(n/cols)*22}" r="9" fill="url(#${id}-${n<a?0:1})" stroke="#36465c" stroke-width="1.2"/>`).join('');return `<svg class="mt-scoops${pot?' mt-pot-art':''}" viewBox="0 0 ${cols*23+8} ${height+ (pot?23:0)}" aria-hidden="true">${defs}${pot?`<path d="M2 2h${cols*23+3}v${height-4}q0 20-25 20H27Q2 ${height+18} 2 ${height-2}Z" fill="#fff" fill-opacity=".8" stroke="#526b7b" stroke-width="3"/>`:''}${tokens}${pot?`<path d="M1 4h${cols*23+6}" stroke="#526b7b" stroke-width="7" stroke-linecap="round"/>`:''}</svg>`;}
export function mixingJar(ingredient){const pair={ingredients:[ingredient,ingredient]}, {id,defs}=setup(pair);return `<svg class="mt-jar-art" viewBox="0 0 120 130" aria-hidden="true">${defs}<ellipse cx="60" cy="122" rx="45" ry="5" fill="#193b59" opacity=".12"/><path d="M29 20h62v13q13 9 13 20v56q0 12-14 12H30q-14 0-14-12V53q0-11 13-20Z" fill="url(#${id}-0)" stroke="#36465c" stroke-width="3"/><path d="M23 45v53" stroke="#fff" stroke-width="5" opacity=".55" stroke-linecap="round"/><rect x="25" y="11" width="70" height="17" rx="5" fill="#c5d5df" stroke="#36465c" stroke-width="3"/><path d="M31 17h58" stroke="#36465c" stroke-width="2"/><rect x="28" y="61" width="64" height="37" rx="5" fill="#fffdf5" stroke="#36465c"/><text x="60" y="85" text-anchor="middle" fill="#223c53" font-size="16" font-family="sans-serif">${esc(ingredient.label)}</text></svg>`;}
export function mixingStripe(pair,a,b,rgb){if(!a&&!b)return '';const {id,defs}=setup(pair),split=240*a/(a+b);return `<div class="mt-stripe-art"><svg viewBox="0 0 248 55" aria-hidden="true">${defs}<path d="M5 3 239 5 245 24 7 23Z" fill="rgb(${rgb.join(',')})"/><rect x="4" y="33" width="${split}" height="17" fill="url(#${id}-0)"/><rect x="${4+split}" y="33" width="${240-split}" height="17" fill="url(#${id}-1)"/><rect x="4" y="33" width="240" height="17" fill="none" stroke="#36465c"/></svg></div>`;}
